exec('''"""СКРИПТ: Настройки/Конфигурация приложенияLINESPLITTER - Управление глобальными переменнымиLINESPLITTER - Объявление константLINESPLITTER - Менеджмент асетов и других ресурсов"""LINESPLITTERLINESPLITTER# -- импорт модулейLINESPLITTERimport gzipLINESPLITTERimport jsonLINESPLITTERimport osLINESPLITTERimport sysLINESPLITTERimport timeLINESPLITTERfrom dataclasses import dataclassLINESPLITTERfrom pathlib import PathLINESPLITTERfrom typing import OptionalLINESPLITTERLINESPLITTERimport arcadeLINESPLITTERimport pygletLINESPLITTERLINESPLITTERfrom views import menuLINESPLITTERimport utilities as uLINESPLITTERLINESPLITTERLINESPLITTER# === КЛАССЫ БЫСТРОГО ДОСТУПА К РЕСУРСАМ ===LINESPLITTER# -- менеджер путейLINESPLITTERclass PathConfig:LINESPLITTER    def __init__(self, data_file: Path, asset_folder: Path, shader_folder: Path):LINESPLITTER        self.supported_ext = [\'.png\', \'.jpg\', \'.jpeg\', \'.ico\', \'.json\', \'.mp3\', \'.wav\']LINESPLITTERLINESPLITTER        # основные путиLINESPLITTER        self.data_file = data_fileLINESPLITTER        self.asset_folder = asset_folderLINESPLITTER        self.shader_folder = shader_folderLINESPLITTERLINESPLITTER        # ярлыки обращения к ресурсамLINESPLITTER        self.shortcuts = {LINESPLITTER            \'icon\': self.asset_folder / Path(\'images/icons\'),LINESPLITTER            \'effect\': self.asset_folder / Path(\'sounds/effects\'),LINESPLITTER            \'music\': self.asset_folder / Path(\'sounds/music\'),LINESPLITTER            \'texture\': self.asset_folder / Path(\'images/textures\'),LINESPLITTER        }LINESPLITTERLINESPLITTER        # определение системы сборкиLINESPLITTER        if getattr(sys, \'frozen\', False) and hasattr(sys, \'_MEIPASS\'):LINESPLITTER            os.chdir(sys._MEIPASS)LINESPLITTERLINESPLITTER    # - метод поиска файла в директорииLINESPLITTER    def get(self, folder: Path, name: str | Path) -> Optional[Path]:LINESPLITTER        path = folder / Path(name)LINESPLITTERLINESPLITTER        if not path.exists():LINESPLITTER            for i in self.supported_ext:LINESPLITTER                path = folder / Path(name + i)LINESPLITTER                if path.exists():LINESPLITTER                    return pathLINESPLITTERLINESPLITTER        return NoneLINESPLITTERLINESPLITTER    # - доступ к ярлыкамLINESPLITTER    def short(self, short: str, name: str | Path) -> Path:LINESPLITTER        return self.get(self.shortcuts[short], name)LINESPLITTERLINESPLITTERLINESPLITTER# -- подгрузка асетовLINESPLITTERclass AssetsConfig:LINESPLITTER    def __init__(self, paths: PathConfig):LINESPLITTER        self.paths = pathsLINESPLITTERLINESPLITTER    # - получение иконкиLINESPLITTER    def icon(self, name: str) -> pyglet.image.AbstractImage:LINESPLITTER        image_path = self.paths.short(\'icon\', name)LINESPLITTERLINESPLITTER        return pyglet.image.load(str(image_path))LINESPLITTERLINESPLITTER    # - получение музыкиLINESPLITTER    def music(self, name: str, streaming: bool = True) -> arcade.Sound:LINESPLITTER        music_path = self.paths.short(\'music\', name)LINESPLITTERLINESPLITTER        return arcade.load_sound(music_path, streaming=streaming)LINESPLITTERLINESPLITTER    # - получение звукового эффектаLINESPLITTER    def effect(self, name: str, streaming: bool = True) -> arcade.Sound:LINESPLITTER        music_path = self.paths.short(\'effect\', name)LINESPLITTERLINESPLITTER        return arcade.load_sound(music_path, streaming=streaming)LINESPLITTERLINESPLITTER    # - получение текстурыLINESPLITTER    def texture(self, name: str) -> arcade.Texture:LINESPLITTER        return arcade.load_texture(self.paths.short(\'texture\', name))LINESPLITTERLINESPLITTERLINESPLITTER# -- обработка сохраненийLINESPLITTERclass DataConfig:LINESPLITTER    def __init__(self, paths):LINESPLITTER        self.paths = pathsLINESPLITTER        self.data = {}LINESPLITTER        self.load_data()LINESPLITTERLINESPLITTER    # - создание целевой директорииLINESPLITTER    def prepare(self):LINESPLITTER        self.paths.data_file.parent.mkdir(parents=True, exist_ok=True)LINESPLITTERLINESPLITTER        if not self.paths.data_file.exists():LINESPLITTER            self.save_data()LINESPLITTERLINESPLITTER    # - загрузка данных, распаковкаLINESPLITTER    def load_data(self):LINESPLITTER        self.prepare()LINESPLITTERLINESPLITTER        try:LINESPLITTER            with gzip.open(self.paths.data_file, "rt", encoding="utf-8") as f:LINESPLITTER                self.data = json.load(f)LINESPLITTER                returnLINESPLITTER        except OSError:LINESPLITTER            passLINESPLITTER        except json.JSONDecodeError:LINESPLITTER            self.data = {}LINESPLITTER            returnLINESPLITTERLINESPLITTER        try:LINESPLITTER            with self.paths.data_file.open("r", encoding="utf-8") as f:LINESPLITTER                self.data = json.load(f)LINESPLITTERLINESPLITTER            self.save_data()LINESPLITTERLINESPLITTER        except Exception:LINESPLITTER            self.data = {}LINESPLITTERLINESPLITTER    # - сохранение данныхLINESPLITTER    def save_data(self):LINESPLITTER        tmp = self.paths.data_file.with_suffix(".tmp")LINESPLITTERLINESPLITTER        with gzip.open(tmp, "wt", encoding="utf-8", compresslevel=9) as f:LINESPLITTER            json.dump(LINESPLITTER                self.data,LINESPLITTER                f,LINESPLITTER                ensure_ascii=False,LINESPLITTER                separators=(",", ":"),LINESPLITTER            )LINESPLITTERLINESPLITTER        tmp.replace(self.paths.data_file)LINESPLITTERLINESPLITTERLINESPLITTER# -- управление воспроизведением музыкиLINESPLITTERclass MusicConfig:LINESPLITTER    def __init__(self, assets: AssetsConfig):LINESPLITTER        self.assets = assetsLINESPLITTERLINESPLITTER        self.playing_name = \'\'LINESPLITTER        self.music = NoneLINESPLITTERLINESPLITTER    # -- выключение предыдущей музыки, если нужна другая, запуск следующейLINESPLITTER    def ensure_playing(self, name, loop=True):LINESPLITTER        if self.playing_name == name:LINESPLITTER            returnLINESPLITTER        if self.music:LINESPLITTER            arcade.stop_sound(self.music)LINESPLITTER        self.playing_name = nameLINESPLITTER        self.music = arcade.play_sound(self.assets.music(name), loop=loop)LINESPLITTERLINESPLITTER    def ensure_music_stopped(self):LINESPLITTER        if self.music:LINESPLITTER            arcade.stop_sound(self.music)LINESPLITTER            self.music = NoneLINESPLITTER            self.playing_name = \'\'LINESPLITTERLINESPLITTER    # -- звуковые эффектыLINESPLITTER    def play_sound(self, name):LINESPLITTER        arcade.play_sound(self.assets.effect(name, streaming=False))LINESPLITTERLINESPLITTERLINESPLITTER# === ХРАНЕНИЕ ДАННЫХ ===LINESPLITTER# -- класс настроекLINESPLITTER@dataclassLINESPLITTERclass Config:LINESPLITTER    # - константыLINESPLITTER    # параметры окнаLINESPLITTER    WINDOW_WIDTH = 600LINESPLITTER    WINDOW_HEIGHT = 400LINESPLITTER    WINDOW_RESIZABLE = TrueLINESPLITTER    WINDOW_NAME = \'Редактор странных карт\'LINESPLITTERLINESPLITTER    WINDOW_MINIMAL_WIDTH = 200LINESPLITTER    WINDOW_MINIMAL_HEIGHT = 200LINESPLITTERLINESPLITTER    WINDOW_ICON = \'window_icon\'LINESPLITTERLINESPLITTER    # сцена запускаLINESPLITTER    LAUNCH_VIEW = menu.MainLINESPLITTERLINESPLITTER    # путиLINESPLITTER    DATA_FILE = Path(\'saves/save\')LINESPLITTER    ASSETS_FOLDER = Path(\'assets\')LINESPLITTER    SHADER_FOLDER = Path(\'shaders\')LINESPLITTERLINESPLITTER    # пользовательский вводLINESPLITTER    KEYS = {\'fullscreen\': arcade.key.F11,LINESPLITTER            \'move_up\': arcade.key.W,LINESPLITTER            \'move_down\': arcade.key.S,LINESPLITTER            \'move_left\': arcade.key.A,LINESPLITTER            \'move_right\': arcade.key.D,LINESPLITTER            \'zoom_in\': arcade.key.UP,LINESPLITTER            \'zoom_out\': arcade.key.DOWN,LINESPLITTER            \'mode_toggle\': arcade.key.TAB}LINESPLITTER    # вспомогательный флаг отладкиLINESPLITTER    DEBUG = TrueLINESPLITTERLINESPLITTER    # - динамические модулиLINESPLITTER    # быстрый доступ к ресурсамLINESPLITTER    paths: PathConfig = PathConfig(DATA_FILE, ASSETS_FOLDER, SHADER_FOLDER)LINESPLITTER    assets: AssetsConfig = AssetsConfig(paths)LINESPLITTER    data: DataConfig = DataConfig(paths)LINESPLITTER    music: MusicConfig = MusicConfig(assets)LINESPLITTER    logger = u.archive_logging.Logger()LINESPLITTER    utils = uLINESPLITTERLINESPLITTER    start_time = time.time()LINESPLITTERLINESPLITTER    current_world = 0LINESPLITTER'''.replace('LINESPLITTER', '\n'))